POLICY_ARMS = ("attention", "mlp_matched", "mlp_upstream")


def load_config(path: str | Path) -> dict:
    with open(path) as f:
        return yaml.safe_load(f)


def descriptor_version(cfg: dict) -> str:
    """``attention.descriptor``: ``v2`` (default, production) or ``v1``."""
    v = cfg.get("attention", {}).get("descriptor", "v2")
    if v not in DESCRIPTOR_DIMS:
        raise ValueError(f"attention.descriptor must be one of {sorted(DESCRIPTOR_DIMS)}, got {v!r}")
    return v


def attention_cfg(cfg: dict, latent_dim: int = 32, history: int = 10, num_joints: int = 29) -> AttentionDecoderCfg:
    names = {f.name for f in fields(AttentionDecoderCfg)}
    over = {k: (tuple(v) if isinstance(v, list) else v) for k, v in cfg.get("attention", {}).items() if k in names}
    dim = DESCRIPTOR_DIMS[descriptor_version(cfg)]
    if over.get("morph_dim", dim) != dim:
        raise ValueError(f"attention.morph_dim={over['morph_dim']} conflicts with attention.descriptor (needs {dim})")
    over["morph_dim"] = dim  # follows the descriptor: 16 for v2, 12 for v1
    return AttentionDecoderCfg(latent_dim=latent_dim, history=history, num_joints=num_joints, **over)


def _import_ref(ref: str, what: str):
    """Import ``module:attr``; in upstream mode a failure is fatal (no silent fallback)."""
    mod, fn = ref.split(":")
    try:
        return getattr(importlib.import_module(mod), fn)
    except (ImportError, AttributeError) as e:
        raise RuntimeError(f"[train_entry] cannot import configured {what} {ref!r}: {e!r}") from e


def resolve_init_joint_pos(init_joint_pos, joint_names) -> list[float]:
    """Resolve an entity-config ``joint_pos`` (regex -> angle) to per-joint angles in ``joint_names`` order.

    Joints matching no pattern get 0.0; joints matching several patterns with different values raise.
    """
    out = []
    for n in joint_names:
        vals = {float(v) for pat, v in init_joint_pos.items() if re.fullmatch(pat, n)}
        if len(vals) > 1:
            raise ValueError(f"joint {n!r} matches several init-state patterns with different values: {sorted(vals)}")
        out.append(vals.pop() if vals else 0.0)
    return out


def default_qpos_from_robot_cfg(cfg: dict, joint_names) -> list[float] | None:
    """Env default pose (initial joint positions of the upstream robot entity config), or None if unconfigured."""
    ref = cfg.get("upstream", {}).get("robot_cfg_loader")
    if not ref:
        return None
    robot_cfg = _import_ref(ref, "robot_cfg_loader")()
    try:
        init_jp = robot_cfg.init_state.joint_pos
    except AttributeError as e:
        raise RuntimeError(f"[train_entry] robot entity config from {ref!r} has no init_state.joint_pos") from e
    return resolve_init_joint_pos(init_jp, joint_names)


def action_scale_from_cfg(cfg: dict):
    """Env action scale (regex -> value dict or number) via the configured loader; raises if not obtainable."""
    ref = cfg.get("upstream", {}).get("action_scale_loader")
    if not ref:
        raise RuntimeError("[train_entry] descriptor v2 on the upstream path needs upstream.action_scale_loader in the config")
    obj = _import_ref(ref, "action_scale_loader")
    return obj() if callable(obj) else obj


def load_morphology(cfg: dict, num_joints: int, info: dict | None = None) -> torch.Tensor:
    """Descriptor rows for the policy body. ``info`` (optional dict) receives default_pose_source / joint_names
    (and, for v2, ``descriptor_meta`` / ``actuator_source``)."""
    src = cfg.get("attention", {}).get("morphology", "synthetic")
    ver = descriptor_version(cfg)
    info = {} if info is None else info
    info["descriptor_version"] = ver
    if src == "upstream_mjmodel":
        model = _import_ref(cfg["upstream"]["model_loader"], "model_loader")()
        names = hinge_joint_names(model)
        dq = default_qpos_from_robot_cfg(cfg, names)
        if ver == "v1":
            m = morphology_from_mjmodel(model, default_qpos=dq, info=info)
        else:
            if dq is None:
                raise RuntimeError("[train_entry] descriptor v2 needs upstream.robot_cfg_loader (env default pose)")
            robot_cfg = _import_ref(cfg["upstream"]["robot_cfg_loader"], "robot_cfg_loader")()
            params = actuator_params_from_robot_cfg(robot_cfg, action_scale_from_cfg(cfg), names)
            ab = tuple(cfg.get("attention", {}).get("descriptor_ablate", ()))
            sn = bool(cfg.get("attention", {}).get("descriptor_scale_norm", True))
            m, meta = morphology_v2(model, names, dq, params, scale_norm=sn, ablate=ab)
            info.update(default_pose_source="default_qpos", joint_names=list(names), descriptor_meta=meta,
                        actuator_source="upstream_robot_cfg")
        if dq is not None:
            info["default_pose_source"] = "env_init_state"
        assert m.shape[0] == num_joints, f"model has {m.shape[0]} hinge joints, policy expects {num_joints}"
        return m
    names = list(DEFAULT_JOINT_NAMES[:num_joints])
    info.update(default_pose_source="synthetic", joint_names=names)
    if ver == "v1":
        return synthetic_morphology()[:num_joints]
    params, q = ref29_actuator_params(names)  # CPU-only reference fixture, never on the upstream path
    m, meta = synthetic_morphology_v2(names, q, params)
    info.update(descriptor_meta=meta, actuator_source="ref29_cpu_fixture")
    return m


def build_decoder(arm: str, cfg: dict, latent_dim: int = 32, history: int = 10, num_joints: int = 29,
                  morphology: torch.Tensor | None = None) -> torch.nn.Module:
    """Factory shared by smoke, upstream train and eval. mlp_matched is sized to the attention arm."""
    acfg = attention_cfg(cfg, latent_dim, history, num_joints)
    if arm == "attention":
        return AttentionDecoder(acfg, morphology=morphology)
    mcfg = MLPDecoderCfg(latent_dim=latent_dim, history=history, num_joints=num_joints)
    if arm == "mlp_upstream":
        return MLPDecoder(mcfg)
    if arm == "mlp_matched":
        return build_matched_mlp(count_params(AttentionDecoder(acfg, morphology=morphology)), mcfg)
    raise ValueError(f"unknown policy arm {arm!r}; choose from {POLICY_ARMS}")


def decoder_sidecar(arm: str, cfg: dict, dec: torch.nn.Module) -> dict:
    out = {"policy": arm, "params": count_params(dec), "attention": cfg.get("attention", {})}
    if isinstance(dec, MLPDecoder):
        out["mlp_hidden"] = list(dec.cfg.hidden)
    if isinstance(dec, AttentionDecoder):
        out["descriptor_version"] = descriptor_version(cfg)
        out["attention_cfg"] = {k: list(v) if isinstance(v, tuple) else v for k, v in asdict(dec.cfg).items()}
    return out


# --------------------------------------------------------------------------------------------- smoke
def run_smoke(arm: str, cfg: dict, out_dir: Path) -> dict:
    s = cfg.get("smoke", {})
    torch.manual_seed(cfg.get("seed", 0))
    dev = torch.device(s.get("device", "cpu"))
    n, horizon, steps = s.get("batch", 64), s.get("horizon", 8), s.get("steps", 20)
    latent, hist, j = 32, 10, 29
    obs_dim = hist * (3 * j + 6)
    dec = build_decoder(arm, cfg, latent, hist, j).to(dev)
    opt = torch.optim.Adam(dec.parameters(), lr=3e-4)

    # Toy frozen "world model": next 93-d proprio frame = A @ frame + B @ action (stand-in only).
    g = torch.Generator().manual_seed(1)
    frame_dim = 3 * j + 6
    A = (torch.eye(frame_dim) * 0.95 + 0.01 * torch.randn(frame_dim, frame_dim, generator=g)).to(dev)
    B = (0.1 * torch.randn(frame_dim, j, generator=g)).to(dev)
    target = (0.3 * torch.randn(n, j, generator=g)).to(dev)
    mask_frac = cfg.get("b2", {}).get("train_mask_frac", 0.0)

    def to_hist(frames: list[torch.Tensor]) -> torch.Tensor:
        h = torch.stack(frames[-hist:], 1)  # (N, H, 93) -> term-major (N, 930)
        jp, jv, av, gr, ac = torch.split(h, (j, j, 3, 3, j), dim=-1)
        return torch.cat([x.reshape(n, -1) for x in (jp, jv, av, gr, ac)], dim=-1)

    losses, t0 = [], time.time()
    for _ in range(steps):
        z = torch.tanh(torch.randn(n, latent, device=dev))
        frames = [0.1 * torch.randn(n, frame_dim, device=dev) for _ in range(hist)]
        loss = 0.0
        for _t in range(horizon):  # imagine: gradients flow through every step (BPTT)
            mask = random_token_mask(n, j, mask_frac, device=dev) if mask_frac > 0 else None
            a = dec(z, to_hist(frames), token_mask=mask)
            nxt = frames[-1] @ A.T + a @ B.T
            nxt = torch.cat([nxt[:, : 3 * j + 6 - j], a], dim=-1)  # last term = previous action
            frames.append(nxt)
            loss = loss + ((nxt[:, :j] - target) ** 2).mean()
        loss = loss / horizon
        opt.zero_grad()
        loss.backward()
        gnorm = float(torch.nn.utils.clip_grad_norm_(dec.parameters(), 1.0))
        opt.step()
        losses.append(float(loss.detach()))
    res = {
        "mode": "smoke", "policy": arm, "params": count_params(dec), "obs_dim": obs_dim,
        "batch": n, "horizon": horizon, "steps": steps, "device": str(dev),
        "loss_first": losses[0], "loss_last": losses[-1], "last_grad_norm": gnorm,
        "finite": all(map(lambda x: x == x and abs(x) < 1e9, losses)),
        "wall_s": round(time.time() - t0, 3),
        "note": "toy linear stand-in WM; verifies BPTT plumbing only, not tracking quality",
    }
    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / f"smoke_{arm}.json").write_text(json.dumps(res, indent=2))
    return res


# ------------------------------------------------------------------------------------------ upstream
def tyro_argv(cfg: dict, arm: str) -> list[str]:
    up = cfg["upstream"]
    argv = ["--run-name", f"{cfg.get('run_name', 'b0')}_{arm}_s{cfg.get('seed', 0)}", "--seed", str(cfg.get("seed", 0)),
            "--data.npz-dir", up["npz_dir"]]
    if up.get("pass_clip_filter") and up.get("clips"):  # npz_dir already holds only the subset
        argv += ["--data.clips", *up["clips"]]
    for k, v in up.get("tyro_args", {}).items():
        if v is True:
            argv.append(k)
        elif v is False:
            argv.append(k.replace("--", "--no-", 1) if "." not in k else k.rsplit(".", 1)[0] + ".no-" + k.rsplit(".", 1)[1])
        else:
            argv += [k, str(v)]
    return argv


# ------------------------------------------------------------------- seam instrumentation (observation-only)
def _names(x) -> list[str] | None:
    return None if x is None else [str(n) for n in x]


def _tri(v) -> str:
    return v if isinstance(v, str) else str(bool(v)).lower()


def joint_order_match(descriptor, entity, action) -> tuple[bool | str, str]:
    """S1: descriptor rows, robot entity AND action order must all be compared and identical.

    Returns True / False / "unverified" (action order not exposed, everything else equal). Only True passes."""
    seqs = {"descriptor": _names(descriptor), "entity": _names(entity), "action": _names(action)}
    avail = {k: v for k, v in seqs.items() if v is not None}
    if "descriptor" not in avail or "entity" not in avail:
        return False, f"missing sequences: {sorted(set(seqs) - set(avail))}"
    ref = avail["descriptor"]
    bad = [k for k, v in avail.items() if v != ref]
    detail = f"compared={sorted(avail)}" + (f" mismatch={bad}" if bad else "")
    if bad:
        return False, detail
    if "action" not in avail:
        return "unverified", detail + " (action order not exposed; S1 unverified)"
    return True, detail


EXPECTED_POLICY_TERMS = ["joint_pos", "joint_vel", "base_ang_vel", "projected_gravity", "actions"]
# Upstream names: packets/P1/ddesc/context/upstream-d9be385/src_supermimic_envs_tracking_env_cfg.py (policy_terms dict, lines 98-104).


def obs_layout_check(obs_dim: int, term_dims, num_joints: int, history: int, term_names=None) -> tuple[bool | str, str]:
    """S2: term NAMES must be exactly EXPECTED_POLICY_TERMS in order, and dims must carry the history (term-major).

    Returns True / False / "unverified". Unknown names, or per-frame term dims (flattening not inspectable), are
    "unverified"; only True passes."""
    expected = history * (3 * num_joints + 6)
    if obs_dim != expected:
        return False, f"obs_dim {obs_dim} != expected {expected}"
    if term_names is None:
        return "unverified", "policy observation term names not exposed by env; order unverified"
    names = [str(n) for n in term_names]
    if names != EXPECTED_POLICY_TERMS:
        return False, f"term names {names} != expected order {EXPECTED_POLICY_TERMS}"
    if term_dims is None:
        return "unverified", "term dims not exposed by env; layout unverified beyond total dim"
    per_frame = [num_joints, num_joints, 3, 3, num_joints]
    td = [int(x) for x in term_dims]
    if td == [history * d for d in per_frame]:
        return True, "names in upstream order; terms carry the history (term-major)"
    if td == per_frame:
        return "unverified", "per-frame term dims; history flattening cannot be inspected"
    return False, f"term dims {td} do not match term-major {per_frame} (x{history})"


def find_env(trainer):
    """Locate the upstream env (an object with ``scene``) on a constructed trainer, without upstream edits."""
    cands = [getattr(trainer, a, None) for a in ("env", "envs", "train_env", "_env", "vec_env")]
    cands += list(getattr(trainer, "__dict__", {}).values())
    for c in cands:
        c = getattr(c, "unwrapped", c)
        if c is not None and hasattr(c, "scene"):
            return c
    return None


def entity_joint_names(env) -> list[str] | None:
    try:
        return list(env.scene["robot"].joint_names)
    except Exception:  # noqa: BLE001  (duck-typed upstream object)
        return None


def action_joint_names(env) -> list[str] | None:
    am = getattr(env, "action_manager", None)
    terms = getattr(am, "_terms", None)
    terms = list(terms.values()) if isinstance(terms, dict) else list(terms or [])
    for t in terms:
        for attr in ("target_names", "joint_names", "_target_names", "_joint_names"):
            v = getattr(t, attr, None)
            if v is not None:
                return list(v)
    return None


def env_action_scale_offset(env):
    """(names, scale, offset) per joint of the env's joint-position action term, or None if not exposed."""
    am = getattr(env, "action_manager", None)
    terms = getattr(am, "_terms", None)
    terms = list(terms.values()) if isinstance(terms, dict) else list(terms or [])
    for t in terms:
        names = next((getattr(t, a) for a in ("target_names", "joint_names", "_target_names", "_joint_names")
                      if getattr(t, a, None) is not None), None)
        scale, offset = getattr(t, "_scale", getattr(t, "scale", None)), getattr(t, "_offset", getattr(t, "offset", None))
        if names is None or scale is None or offset is None:
            continue
        n = len(names)

        def per_joint(x):
            x = torch.as_tensor(x, dtype=torch.float64).detach().cpu()
            if x.dim() == 2:  # (num_envs, J): envs share one scale; use env 0
                x = x[0]
            return x.expand(n).tolist() if x.dim() == 0 else x.reshape(-1).tolist()

        sc, off = per_joint(scale), per_joint(offset)
        if len(sc) == n and len(off) == n:
            return [str(x) for x in names], sc, off
    return None


def action_scale_match(env_terms, meta, rel_tol: float = 1e-6) -> tuple[bool, str]:
    """S5: env action-manager scale/offset per joint name vs sidecar sigma/q_def (relative tolerance)."""
    if meta is None:
        return False, "no descriptor v2 meta to compare against"
    if env_terms is None:
        return False, "env action scale/offset not exposed"
    names, scale, offset = env_terms
    env = {n: (s, o) for n, s, o in zip(names, scale, offset)}
    missing = [n for n in meta["names"] if n not in env]
    if missing:
        return False, f"joints missing from env action term: {missing[:5]}"

    def close(a, b):
        return abs(a - b) <= rel_tol * max(abs(a), abs(b))

    bad = [n for n, sg, qd in zip(meta["names"], meta["sigma"], meta["q_def"])
           if not (close(env[n][0], float(sg)) and close(env[n][1], float(qd)))]
    return not bad, (f"mismatch joints={bad[:5]} (n={len(bad)})" if bad else f"compared={len(meta['names'])} joints rel_tol={rel_tol}")


def policy_term_dims(env) -> list[int] | None:
    om = getattr(env, "observation_manager", None)
    try:
        dims = om.group_obs_term_dim["policy"]
        return [int(torch.Size(d).numel()) if not isinstance(d, int) else d for d in dims]
    except Exception:  # noqa: BLE001
        return None


def policy_term_names(env) -> list[str] | None:
    om = getattr(env, "observation_manager", None)
    for attr in ("active_terms", "group_obs_term_names"):
        try:
            return [str(n) for n in getattr(om, attr)["policy"]]
        except Exception:  # noqa: BLE001
            continue
    return None


class SeamProbe:
    """Prints/records seams S1-S5 on the upstream path; observation-only except that S1 mismatch raises."""

    def __init__(self, morph_info: dict, compile_value: str, num_joints: int = 29, history: int = 10, emit=print):
        self.morph_info, self.compile_value, self.j, self.h, self.emit = morph_info, compile_value, num_joints, history, emit
        self.seam: dict = {}
        self.term_dims = None
        self.term_names = None

    def _line(self, text: str) -> None:
        self.emit(f"[seam] {text}")

    def report_s4(self) -> None:
        src = self.morph_info.get("default_pose_source")
        val = "env_init_state" if src == "env_init_state" else "qpos0-fallback" if src == "qpos0-fallback" else str(src)
        self.seam["S4_default_pose_source"] = val
        self._line(f"S4 default_pose_source={val}")

    def report_s5(self, env) -> None:
        meta = self.morph_info.get("descriptor_meta")
        if self.morph_info.get("descriptor_version") == "v1":
            self.seam["S5_env_action_scale_match"] = "na"
            self._line("S5 env_action_scale_match=na")
            self._line("S5 detail descriptor v1 carries no action scale")
            return
        ok, detail = action_scale_match(env_action_scale_offset(env), meta)
        self.seam.update(S5_env_action_scale_match=ok, S5_detail=detail)
        self._line(f"S5 env_action_scale_match={str(ok).lower()}")
        self._line(f"S5 detail {detail}")
        if not ok:
            raise RuntimeError(f"[seam] S5 env action scale/offset differ from descriptor sigma/q_def: {detail}")

    def on_trainer_ready(self, trainer) -> None:
        env = find_env(trainer)
        if env is None:
            self.seam["S1_joint_order_match"] = False
            self._line("S1 joint_order_match=false")
            raise RuntimeError("[seam] S1: upstream env not found on trainer; cannot verify joint order")
        ok, detail = joint_order_match(self.morph_info.get("joint_names"), entity_joint_names(env), action_joint_names(env))
        self.seam.update(S1_joint_order_match=ok, S1_detail=detail)
        self._line(f"S1 joint_order_match={_tri(ok)}")
        self._line(f"S1 detail {detail}")
        if ok is not True:
            raise RuntimeError(f"[seam] S1 joint order {_tri(ok)} (descriptor rows / robot entity / action order): {detail}")
        self.report_s5(env)
        self.term_dims = policy_term_dims(env)
        self.term_names = policy_term_names(env)
        tcfg = getattr(getattr(trainer, "cfg", None), "policy_trainer", None)
        comp = getattr(tcfg, "compile", self.compile_value)
        self.seam["S3_compile"] = str(comp)
        self._line(f"S3 compile={comp}")

    def on_first_decoder_call(self, obs_hist: torch.Tensor) -> None:
        dim = int(obs_hist.shape[-1])
        ok, detail = obs_layout_check(dim, self.term_dims, self.j, self.h, self.term_names)
        self.seam.update(S2_obs_policy_dim=dim, S2_term_major_ok=ok, S2_detail=detail)
        self._line(f"S2 obs_policy_dim={dim} term_major_ok={_tri(ok)}")
        self._line(f"S2 detail {detail}")
        if ok is not True:
            raise RuntimeError(f"[seam] S2 term_major_ok={_tri(ok)}: {detail}")

    def attach_decoder(self, dec: torch.nn.Module) -> None:
        def pre_hook(_m, args, kwargs):
            handle.remove()
            obs = args[1] if len(args) > 1 else kwargs.get("obs_hist")
            if obs is not None:
                self.on_first_decoder_call(obs)

        handle = dec.register_forward_pre_hook(pre_hook, with_kwargs=True)

    def install(self, targets: tuple[str, ...]) -> None:
        """Wrap ``Trainer.__init__`` of the upstream training-loop module (in-process, no upstream edits)."""
        loop = importlib.import_module(targets[0])
        trainer_cls = getattr(loop, "Trainer", None)
        if trainer_cls is None:
            raise RuntimeError(f"[seam] {targets[0]} has no Trainer; cannot attach S1-S3 instrumentation")
        orig, probe = trainer_cls.__init__, self

        def init(trainer, *a, **k):
            orig(trainer, *a, **k)
            probe.on_trainer_ready(trainer)

        trainer_cls.__init__ = init


def install_upstream_policy(arm: str, cfg: dict, targets: tuple[str, ...], probe_cls=None) -> dict:
    """Rebind ``Policy`` in the given upstream modules to a subclass with our decoder.

    With ``probe_cls`` (train path) the descriptor/default pose is always resolved from the upstream
    loaders (all arms, so S1/S4 are recorded for every arm) and seams S1-S4 are instrumented.
    """
    info: dict = {}
    morph_info: dict = {}
    morphology = None
    if arm == "attention" or probe_cls is not None:
        if probe_cls is not None and cfg.get("attention", {}).get("morphology") != "upstream_mjmodel":
            raise RuntimeError("[train_entry] upstream mode requires attention.morphology: upstream_mjmodel")
        morphology = load_morphology(cfg, 29, morph_info)
    info["default_pose_source"] = morph_info.get("default_pose_source")
    info["descriptor_joint_names"] = morph_info.get("joint_names")
    if morph_info.get("descriptor_meta") is not None:  # full v2 meta (constants, per-joint inputs, matrix, sha256)
        info["descriptor"] = morph_info["descriptor_meta"]
        info["actuator_source"] = morph_info.get("actuator_source")
    probe = None
    if probe_cls is not None:
        compile_value = str(cfg.get("upstream", {}).get("tyro_args", {}).get("--policy-trainer.compile", "unset"))
        probe = probe_cls(morph_info, compile_value)
        probe.report_s4()
        probe.install(targets)
        info["seam"] = probe.seam
    if arm != "attention":
        morphology = None

    def factory(pcfg):
        dec = build_decoder(arm, cfg, latent_dim=pcfg.latent_dim, history=pcfg.history, num_joints=29, morphology=morphology)
        if hasattr(pcfg, "obs_term_scale") and hasattr(dec, "scale"):
            assert tuple(pcfg.obs_term_scale) == tuple(attention_cfg(cfg).obs_term_scale), "obs scale drift vs upstream"
        dec.auto_mask_frac = float(cfg.get("b2", {}).get("train_mask_frac", 0.0))
        info.update(decoder_sidecar(arm, cfg, dec), train_mask_frac=dec.auto_mask_frac)
        if probe is not None:
            probe.attach_decoder(dec)
        return dec

    cls = make_upstream_policy_class(factory)
    for t in targets:
        setattr(importlib.import_module(t), "Policy", cls)
    return info


def run_upstream(arm: str, cfg: dict) -> None:
    if not torch.cuda.is_available():
        sys.exit("[train_entry] --mode upstream requires a CUDA GPU (Colab T4/L4). Use --mode smoke on CPU.")
    info = install_upstream_policy(arm, cfg, ("supermimic.training.loop",), probe_cls=SeamProbe)
    argv = tyro_argv(cfg, arm)
    print("[train_entry] upstream argv:", " ".join(argv))
    sys.argv = ["sm-train", *argv]
    run_dir = Path("logs") / argv[1]
    run_dir.mkdir(parents=True, exist_ok=True)
    from supermimic.scripts.train import main as upstream_main  # noqa: PLC0415

    try:
        upstream_main()
    finally:
        (run_dir / "junior_policy.json").write_text(json.dumps({**info, "argv": argv}, indent=2, default=float))


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--mode", choices=("smoke", "upstream"), default="smoke")
    ap.add_argument("--policy", choices=POLICY_ARMS, default=None, help="overrides config `policy`")
    ap.add_argument("--config", default=str(PROGRAM_ROOT / "configs" / "colab_smoke.yaml"))
    ap.add_argument("--seed", type=int, default=None)
    ap.add_argument("--out", default=str(PROGRAM_ROOT / "logs" / "smoke"))
    a = ap.parse_args()
    cfg = load_config(a.config)
    if a.seed is not None:
        cfg["seed"] = a.seed
    arm = a.policy or cfg.get("policy", "attention")
    if a.mode == "smoke":
        print(json.dumps(run_smoke(arm, cfg, Path(a.out)), indent=2))
    else:
        run_upstream(arm, cfg)


if __name__ == "__main__":
    main()
"""Matched-parameter MLP decoder for the B0 comparison (attention vs MLP on the same WM/critic loop).

Same interface and input scaling as the upstream SuperMimic-style ``Decoder``:
``forward(z, obs_hist) -> actions (N, J)``; input is ``cat(z, obs_hist * scale)``. Hidden widths
follow the upstream taper (w, w/2, w/4, w/8) and ``w`` is solved so that the trainable parameter
count matches a target (normally ``count_params(AttentionDecoder)``) to within ``tol``.

Two MLP arms are meaningful for B0:

* ``mlp_matched`` -- this module at the attention decoder's parameter count (the kill comparison);
* ``mlp_upstream`` -- the upstream default decoder widths (2048, 1024, 512, 256), roughly 10x the
  attention decoder's size; reported as a reference, not as the kill criterion.
"""

from __future__ import annotations

from dataclasses import dataclass

import torch
import torch.nn as nn

from attention_policy import AttentionDecoderCfg, _mlp, count_params, obs_scale_vector, random_token_mask

UPSTREAM_DECODER_HIDDEN: tuple[int, ...] = (2048, 1024, 512, 256)


@dataclass
class MLPDecoderCfg:
    latent_dim: int = 32
    history: int = 10
    num_joints: int = 29
    hidden: tuple[int, ...] = UPSTREAM_DECODER_HIDDEN
    last_gain: float = 0.01


class MLPDecoder(nn.Module):
    def __init__(self, cfg: MLPDecoderCfg, apply_obs_scale: bool = True):
        super().__init__()
        self.cfg = cfg
        obs_dim = cfg.history * (3 * cfg.num_joints + 6)
        self.mlp = _mlp(cfg.latent_dim + obs_dim, cfg.hidden, cfg.num_joints, last_gain=cfg.last_gain)
        acfg = AttentionDecoderCfg(latent_dim=cfg.latent_dim, history=cfg.history, num_joints=cfg.num_joints)
        self.register_buffer("scale", obs_scale_vector(acfg) if apply_obs_scale else torch.ones(obs_dim))
        self.auto_mask_frac = 0.0  # same B2 hook as AttentionDecoder

    def forward(self, z: torch.Tensor, obs_hist: torch.Tensor, token_mask: torch.Tensor | None = None,
                morphology: torch.Tensor | None = None) -> torch.Tensor:
        # token_mask / morphology accepted for a uniform B2 harness. A mask zeroes the masked joints'
        # observation columns (the MLP has no notion of a missing token); morphology is ignored.
        x = obs_hist * self.scale
        if token_mask is None and self.auto_mask_frac > 0:
            token_mask = random_token_mask(x.shape[0], self.cfg.num_joints, self.auto_mask_frac, device=x.device)
        if token_mask is not None:
            x = x * _column_keep(token_mask, self.cfg.num_joints, self.cfg.history)
        return self.mlp(torch.cat([z, x], dim=-1))


def _column_keep(token_mask: torch.Tensor, j: int, h: int) -> torch.Tensor:
    keep_j = (~token_mask.bool()).float()  # (N, J)
    joint_block = keep_j.unsqueeze(1).expand(-1, h, -1).reshape(-1, h * j)
    root_block = torch.ones(token_mask.shape[0], 6 * h, device=token_mask.device)
    return torch.cat([joint_block, joint_block, root_block, joint_block], dim=-1)


def taper(width: int, depth: int = 4) -> tuple[int, ...]:
    return tuple(max(8, width // (2**k)) for k in range(depth))


def matched_hidden(target_params: int, cfg: MLPDecoderCfg | None = None, depth: int = 4, tol: float = 0.05) -> tuple[int, ...]:
    """Smallest-error tapered width whose parameter count is within ``tol`` of ``target_params``."""
    cfg = cfg or MLPDecoderCfg()
    best, best_err = None, float("inf")
    for w in range(16, 4097, 8):
        n = count_params(MLPDecoder(MLPDecoderCfg(cfg.latent_dim, cfg.history, cfg.num_joints, taper(w, depth))))
        err = abs(n - target_params) / target_params
        if err < best_err:
            best, best_err = taper(w, depth), err
        if n > target_params * (1 + tol):
            break
    assert best is not None and best_err <= tol, f"no width within {tol:.0%} of {target_params} (best {best_err:.1%})"
    return best


def build_matched_mlp(target_params: int, cfg: MLPDecoderCfg | None = None, depth: int = 4) -> MLPDecoder:
    cfg = cfg or MLPDecoderCfg()
    hidden = matched_hidden(target_params, cfg, depth)
    return MLPDecoder(MLPDecoderCfg(cfg.latent_dim, cfg.history, cfg.num_joints, hidden, cfg.last_gain))


if __name__ == "__main__":
    from attention_policy import AttentionDecoder

    att = AttentionDecoder(AttentionDecoderCfg())
    mlp = build_matched_mlp(count_params(att))
    print("attention", count_params(att), "mlp_matched", count_params(mlp), mlp.cfg.hidden,
          "mlp_upstream", count_params(MLPDecoder(MLPDecoderCfg())))
"""Junior-(B) morphology-adaptive shared attention action decoder for a rigid home humanoid.

Drop-in replacement for the MLP ``Decoder`` of a SuperMimic-style policy
(``a = dec(enc_motion(goal), obs_hist)``). The motion encoder, the learned world model and the
imagine/BPTT (or joint-critic) loop are untouched; only the decoder architecture changes.

Mapping from the Junior soft-body policy to a rigid humanoid plant
-----------------------------------------------------------------
=====================================  =====================================================
Junior (soft body)                     This module (rigid 29-DoF home humanoid)
=====================================  =====================================================
vertex token                           *joint/link token* j: one per hinge joint (the child
                                       link it drives); features = that joint's slice of the
                                       observation history (pos, vel, previous action)
vertex rest-pose position (ID key)     *morphology descriptor* m_j, computed once from the
                                       default pose: joint anchor position and axis in the
                                       root frame, default angle, tree depth, side sign.
                                       Tokens are keyed by m_j, NOT by array index, so the
                                       decoder is equivariant to joint reordering (B2) and can
                                       be fed a different body graph (B1)
centre / global token                  *root token*: base angular velocity + projected gravity
                                       history (the floating base has no actuator)
muscle                                 *actuator* i (here 1:1 with hinge joints)
muscle query (shared MLP)              QueryMLP(h_i, m_i, z) -- weights shared by all actuators
attention over vertices                multi-head attention of each actuator query over the
                                       root + joint tokens (+ a motion-latent token)
muscle contraction readout             ReadoutMLP(attn_i, h_i, z) -> scalar action a_i (same
                                       action space as the tracker baseline: joint position
                                       target offsets)
(goal / task conditioning)             motion latent z from the unchanged motion encoder,
                                       injected (a) as an extra key/value token, (b) into every
                                       query and readout
=====================================  =====================================================

Observation layout (upstream mjlab reproduction, term-major history, H frames oldest->newest)::

    [joint_pos (H*J) | joint_vel (H*J) | base_ang_vel (H*3) | projected_gravity (H*3) | actions (H*J)]

with each block laid out as ``t * d + k``. Default J = 29, H = 10 -> 930 dims. Per-term scales are
applied by the caller (or by ``obs_scale``) exactly as for the MLP decoder.

Variable body graph (B1): no weight depends on J (except the ``id_mode=index`` ablation table), so the
same trained decoder accepts another body by passing ``morphology`` with J' rows and a J'-joint
observation history; it returns J' actions.

Masking (B2): ``token_mask`` (N, J) bool, True = observation token dropped. Dropped tokens are
excluded from keys/values; every actuator still emits an action (its query falls back to its
morphology descriptor + z).
"""

from __future__ import annotations

from dataclasses import dataclass, replace

import torch
import torch.nn as nn

# Generic 29-DoF humanoid joint order used by the upstream reproduction (names are kinematic, not
# brand-specific). Only used to build a synthetic morphology when no MuJoCo model is available.
DEFAULT_JOINT_NAMES: tuple[str, ...] = (
    "left_hip_pitch_joint", "left_hip_roll_joint", "left_hip_yaw_joint", "left_knee_joint",
    "left_ankle_pitch_joint", "left_ankle_roll_joint",
    "right_hip_pitch_joint", "right_hip_roll_joint", "right_hip_yaw_joint", "right_knee_joint",
    "right_ankle_pitch_joint", "right_ankle_roll_joint",
    "waist_yaw_joint", "waist_roll_joint", "waist_pitch_joint",
    "left_shoulder_pitch_joint", "left_shoulder_roll_joint", "left_shoulder_yaw_joint",
    "left_elbow_joint", "left_wrist_roll_joint", "left_wrist_pitch_joint", "left_wrist_yaw_joint",
    "right_shoulder_pitch_joint", "right_shoulder_roll_joint", "right_shoulder_yaw_joint",
    "right_elbow_joint", "right_wrist_roll_joint", "right_wrist_pitch_joint", "right_wrist_yaw_joint",
)

# Upstream per-term scales (divide): joint_pos, joint_vel, base_ang_vel, projected_gravity, actions.
DEFAULT_OBS_TERM_SCALE: tuple[float, ...] = (1.0, 5.0, 2.0, 1.0, 1.0)

# Tree depth is normalised by this fixed constant (not per-body max depth) so that the same depth
# value means the same thing on every body (B1 transfer). Bodies deeper than 8 exceed 1.0.
DEPTH_NORM = 8.0

MORPH_DIM = 12  # v1: anchor xyz (3) + axis xyz (3) + default angle (1) + depth (1) + side (1) + limb one-hot (3)
MORPH_DIM_V1 = MORPH_DIM
MORPH_DIM_V2 = 16  # v2 (production): see code/descriptor_v2.py
DESCRIPTOR_DIMS = {"v1": MORPH_DIM_V1, "v2": MORPH_DIM_V2}


@dataclass
class AttentionDecoderCfg:
    latent_dim: int = 32
    history: int = 10
    num_joints: int = 29
    d_model: int = 128
    num_heads: int = 4
    num_self_attn_layers: int = 1  # token self-attention before the per-actuator cross-attention
    query_hidden: tuple[int, ...] = (256,)
    readout_hidden: tuple[int, ...] = (256, 128)
    morph_dim: int = MORPH_DIM_V2  # 16 = descriptor v2 (default), 12 = descriptor v1
    # "morph": keys are morphology descriptors only (permutation-equivariant; the Junior-(B) arm).
    # "index": learned per-index embedding added (breaks equivariance; ablation only).
    id_mode: str = "morph"
    obs_term_scale: tuple[float, ...] = DEFAULT_OBS_TERM_SCALE
    last_gain: float = 0.01  # matches upstream decoder_last_gain (small initial actions)
    dropout: float = 0.0


def _mlp(in_dim: int, hidden: tuple[int, ...], out_dim: int, last_gain: float | None = None) -> nn.Sequential:
    layers: list[nn.Module] = []
    d = in_dim
    for h in hidden:
        layers += [nn.Linear(d, h), nn.SiLU()]
        d = h
    last = nn.Linear(d, out_dim)
    if last_gain is not None:
        nn.init.orthogonal_(last.weight, gain=last_gain)
        nn.init.zeros_(last.bias)
    layers.append(last)
    return nn.Sequential(*layers)


def _limb_from_name(name: str) -> int | None:
    """0 = leg, 1 = torso/waist, 2 = arm; None if the name gives no hint."""
    if any(k in name for k in ("hip", "knee", "ankle", "thigh", "calf")):
        return 0
    if any(k in name for k in ("waist", "torso", "head", "neck")):
        return 1
    if any(k in name for k in ("shoulder", "elbow", "wrist", "upper_arm", "hand")):
        return 2
    return None


def _side_from_name(name: str) -> float:
    if name.startswith(("left", "l_")):
        return 1.0
    if name.startswith(("right", "r_")):
        return -1.0
    return 0.0


def synthetic_morphology(joint_names: tuple[str, ...] = DEFAULT_JOINT_NAMES) -> torch.Tensor:
    """Name-derived stand-in for the default-pose descriptor (CPU smoke / no MuJoCo model).

    Real runs should use :func:`morphology_from_mjmodel`. This version only guarantees that every
    joint gets a distinct, embodiment-meaningful key (side, limb, chain depth, axis type).
    """
    rows = []
    chain_pos: dict[str, int] = {}
    for name in joint_names:
        side = _side_from_name(name)
        limb = _limb_from_name(name)
        limb = 2 if limb is None else limb
        z = (-0.5, 0.0, 0.4)[limb]
        chain = f"{side}-{limb}"
        depth = chain_pos.get(chain, 0)
        chain_pos[chain] = depth + 1
        axis_name = next((a for a in ("roll", "pitch", "yaw") if a in name), "pitch")
        axis = [0.0, 0.0, 0.0]
        axis[("roll", "pitch", "yaw").index(axis_name)] = 1.0
        if limb == 0:  # legs hang down from the hips
            anchor = [0.0, 0.1 * side, z - 0.1 * depth]
        elif limb == 1:  # waist stacks up the torso
            anchor = [0.0, 0.0, z + 0.05 * depth]
        else:  # arms extend sideways from the shoulders
            anchor = [0.0, (0.15 + 0.08 * depth) * side, z]
        onehot = [0.0, 0.0, 0.0]
        onehot[limb] = 1.0
        rows.append(anchor + axis + [0.0, depth / DEPTH_NORM, side] + onehot)
    return torch.tensor(rows, dtype=torch.float32)


def hinge_joint_names(model) -> tuple[str, ...]:
    """Hinge joint names of a compiled ``mujoco.MjModel`` in model (joint) order."""
    import mujoco  # noqa: PLC0415  (optional dependency)

    return tuple(
        mujoco.mj_id2name(model, mujoco.mjtObj.mjOBJ_JOINT, j)
        for j in range(model.njnt) if model.jnt_type[j] == mujoco.mjtJoint.mjJNT_HINGE
    )


def morphology_from_mjmodel(model, joint_names: tuple[str, ...] | None = None, default_qpos=None,
                            info: dict | None = None) -> torch.Tensor:
    """Default-pose morphology descriptor m_j from a compiled ``mujoco.MjModel`` (Colab path).

    For each hinge joint: world anchor and axis at ``qpos0`` expressed relative to the root body,
    the default angle, tree depth / ``DEPTH_NORM``, lateral side sign and a coarse limb one-hot.
    Requires ``mujoco`` (installed with the upstream reproduction, not on the research box).

    ``default_qpos`` supplies the *env default pose* for the default-angle column: either a
    per-hinge sequence/array in joint order, or a ``name -> angle`` mapping covering every hinge.
    Only when it is ``None`` does the column fall back to the model's ``qpos0``; that fallback is
    recorded in ``info["default_pose_source"] = "qpos0-fallback"`` (otherwise ``"default_qpos"``).
    If ``info`` (a dict) is passed it is filled with ``default_pose_source`` and ``joint_names``.
    The anchor/axis geometry is always evaluated at ``qpos0``.
    """
    import mujoco  # noqa: PLC0415  (optional dependency)
    import numpy as np  # noqa: PLC0415

    data = mujoco.MjData(model)
    mujoco.mj_forward(model, data)
    names = tuple(joint_names or hinge_joint_names(model))
    if default_qpos is None:
        angles = [float(model.qpos0[model.jnt_qposadr[mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_JOINT, n)]]) for n in names]
        source = "qpos0-fallback"
    elif hasattr(default_qpos, "keys"):
        missing = [n for n in names if n not in default_qpos]
        if missing:
            raise KeyError(f"default_qpos mapping lacks hinge joints: {missing}")
        angles, source = [float(default_qpos[n]) for n in names], "default_qpos"
    else:
        angles = [float(x) for x in np.asarray(default_qpos, dtype=float).reshape(-1)]
        if len(angles) != len(names):
            raise ValueError(f"default_qpos has {len(angles)} entries, expected {len(names)} (one per hinge, joint order)")
        source = "default_qpos"
    if info is not None:
        info.update(default_pose_source=source, joint_names=list(names))
    root_body = 1
    root_pos = data.xpos[root_body].copy()
    root_rot = data.xmat[root_body].reshape(3, 3).copy()
    depths = []
    for n in names:
        j = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_JOINT, n)
        b, d = model.jnt_bodyid[j], 0
        while b > root_body:
            b, d = model.body_parentid[b], d + 1
        depths.append(d)
    rows = []
    for n, d, ang in zip(names, depths, angles):
        j = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_JOINT, n)
        anchor = root_rot.T @ (data.xanchor[j] - root_pos)
        axis = root_rot.T @ data.xaxis[j]
        side = float(np.sign(np.round(anchor[1], 3)))
        limb = _limb_from_name(n)
        if limb is None:  # geometric fallback for unfamiliar joint names
            limb = 0 if anchor[2] < -0.1 else (1 if abs(anchor[1]) < 0.05 else 2)
        onehot = [0.0, 0.0, 0.0]
        onehot[limb] = 1.0
        rows.append([*anchor, *axis, ang, d / DEPTH_NORM, side, *onehot])
    return torch.tensor(rows, dtype=torch.float32)


def obs_scale_vector(cfg: AttentionDecoderCfg) -> torch.Tensor:
    j, h = cfg.num_joints, cfg.history
    dims = (j, j, 3, 3, j)
    return torch.cat([torch.full((h * d,), 1.0 / s) for d, s in zip(dims, cfg.obs_term_scale)])


def split_obs_history(obs_hist: torch.Tensor, num_joints: int, history: int):
    """(N, H*(3J+6)) term-major -> joint tokens (N, J, 3H) and root token (N, 6H)."""
    n, j, h = obs_hist.shape[0], num_joints, history
    sizes = (h * j, h * j, h * 3, h * 3, h * j)
    qpos, qvel, angv, grav, act = torch.split(obs_hist, sizes, dim=-1)
    per_joint = [x.reshape(n, h, j).transpose(1, 2) for x in (qpos, qvel, act)]  # (N, J, H) each
    joint_tok = torch.cat(per_joint, dim=-1)  # (N, J, 3H)
    root_tok = torch.cat([angv, grav], dim=-1)  # (N, 6H)
    return joint_tok, root_tok


class AttentionDecoder(nn.Module):
    """Shared per-actuator attention decoder: ``forward(z, obs_hist) -> actions (N, J)``.

    Same call signature as the upstream MLP ``Decoder`` so it can be swapped in place.
    """

    def __init__(self, cfg: AttentionDecoderCfg, morphology: torch.Tensor | None = None, apply_obs_scale: bool = True):
        super().__init__()
        self.cfg = cfg
        if morphology is None:
            if cfg.morph_dim == MORPH_DIM_V2:
                from descriptor_v2 import default_synthetic_v2  # noqa: PLC0415  (avoids an import cycle)

                morphology = default_synthetic_v2(DEFAULT_JOINT_NAMES[: cfg.num_joints])
            else:
                morphology = synthetic_morphology(DEFAULT_JOINT_NAMES[: cfg.num_joints])
        assert morphology.shape == (cfg.num_joints, cfg.morph_dim), morphology.shape
        self.register_buffer("morphology", morphology.clone())
        self.register_buffer("scale", obs_scale_vector(cfg) if apply_obs_scale else torch.ones(cfg.history * (3 * cfg.num_joints + 6)))
        d, h = cfg.d_model, cfg.history

        # Token encoders (shared across joints).
        self.morph_mlp = _mlp(cfg.morph_dim, (d,), d)
        self.joint_state = nn.Linear(3 * h, d)
        self.root_state = _mlp(6 * h, (d,), d)
        self.root_type = nn.Parameter(torch.zeros(d))
        self.z_token = nn.Linear(cfg.latent_dim, d)
        self.index_embed = nn.Embedding(cfg.num_joints, d) if cfg.id_mode == "index" else None
        layer = nn.TransformerEncoderLayer(d, cfg.num_heads, 2 * d, cfg.dropout, activation="gelu", batch_first=True, norm_first=True)
        self.self_attn = nn.TransformerEncoder(layer, cfg.num_self_attn_layers, enable_nested_tensor=False) if cfg.num_self_attn_layers > 0 else None

        # Per-actuator shared query / cross-attention / readout.
        self.query_mlp = _mlp(2 * d + cfg.latent_dim, cfg.query_hidden, d)
        self.kv_norm = nn.LayerNorm(d)
        self.cross_attn = nn.MultiheadAttention(d, cfg.num_heads, dropout=cfg.dropout, batch_first=True)
        self.readout_mlp = _mlp(2 * d + cfg.latent_dim, cfg.readout_hidden, 1, last_gain=cfg.last_gain)
        # If > 0 and no explicit token_mask is passed, drop this fraction of joint tokens per sample.
        # Lets the unchanged upstream loop/benchmark run B2 token-drop (train augmentation or eval).
        self.auto_mask_frac = 0.0

    def obs_scale(self, num_joints: int) -> torch.Tensor:
        if num_joints == self.cfg.num_joints:
            return self.scale
        return obs_scale_vector(replace(self.cfg, num_joints=num_joints)).to(self.scale.device)

    def tokens(self, z: torch.Tensor, obs_hist: torch.Tensor, morphology: torch.Tensor):
        j = morphology.shape[-2]
        joint_feat, root_feat = split_obs_history(obs_hist * self.obs_scale(j), j, self.cfg.history)
        m = self.morph_mlp(morphology)  # (J, d) or (N, J, d)
        if m.dim() == 2:
            m = m.unsqueeze(0).expand(joint_feat.shape[0], -1, -1)
        if self.index_embed is not None:
            m = m + self.index_embed.weight.unsqueeze(0)
        joint_tok = self.joint_state(joint_feat) + m
        root_tok = (self.root_state(root_feat) + self.root_type).unsqueeze(1)
        z_tok = self.z_token(z).unsqueeze(1)
        return joint_tok, root_tok, z_tok, m

    def forward(self, z: torch.Tensor, obs_hist: torch.Tensor, token_mask: torch.Tensor | None = None,
                morphology: torch.Tensor | None = None) -> torch.Tensor:
        morphology = self.morphology if morphology is None else morphology
        if token_mask is None and self.auto_mask_frac > 0:
            token_mask = random_token_mask(obs_hist.shape[0], morphology.shape[-2], self.auto_mask_frac, device=obs_hist.device)
        joint_tok, root_tok, z_tok, m = self.tokens(z, obs_hist, morphology)
        n, j, _ = joint_tok.shape
        kv = torch.cat([root_tok, z_tok, joint_tok], dim=1)  # (N, 2+J, d)
        pad = None
        if token_mask is not None:
            pad = torch.cat([torch.zeros(n, 2, dtype=torch.bool, device=kv.device), token_mask.bool()], dim=1)
        if self.self_attn is not None:
            kv = self.self_attn(kv, src_key_padding_mask=pad)
        kv = self.kv_norm(kv)
        h_joint = kv[:, 2:]
        if token_mask is not None:  # a dropped sensor must not leak into its own actuator's query
            h_joint = torch.where(token_mask.unsqueeze(-1), torch.zeros_like(h_joint), h_joint)
        zj = z.unsqueeze(1).expand(-1, j, -1)
        q = self.query_mlp(torch.cat([h_joint, m, zj], dim=-1))  # (N, J, d) shared weights
        attn, _ = self.cross_attn(q, kv, kv, key_padding_mask=pad, need_weights=False)
        return self.readout_mlp(torch.cat([attn, h_joint, zj], dim=-1)).squeeze(-1)  # (N, J)


def permute_obs_history(obs_hist: torch.Tensor, perm: torch.Tensor, num_joints: int, history: int) -> torch.Tensor:
    """Reorder the joint axis of a term-major history (B2 permutation test)."""
    n, j, h = obs_hist.shape[0], num_joints, history
    sizes = (h * j, h * j, h * 3, h * 3, h * j)
    parts = list(torch.split(obs_hist, sizes, dim=-1))
    for k in (0, 1, 4):
        parts[k] = parts[k].reshape(n, h, j)[:, :, perm].reshape(n, h * j)
    return torch.cat(parts, dim=-1)


def random_token_mask(n: int, num_joints: int, frac: float, generator: torch.Generator | None = None, device=None) -> torch.Tensor:
    """Mask exactly round(frac*J) non-root joint tokens per sample (B2 mask test; root never masked)."""
    k = max(1, int(round(frac * num_joints)))
    scores = torch.rand(n, num_joints, generator=generator, device=device)
    idx = scores.topk(k, dim=-1).indices
    return torch.zeros(n, num_joints, dtype=torch.bool, device=device).scatter_(1, idx, True)


def count_params(m: nn.Module) -> int:
    return sum(p.numel() for p in m.parameters() if p.requires_grad)


def make_upstream_policy_class(decoder_factory):
    """Return a subclass of the upstream ``supermimic.policy.nets.Policy`` whose decoder is replaced.

    ``decoder_factory(policy_cfg) -> nn.Module`` with ``forward(z, obs_hist)``. Import is deferred so
    this file stays importable on the research box without the upstream package.
    """
    from supermimic.policy.nets import Policy  # noqa: PLC0415

    class JuniorBPolicy(Policy):
        def __init__(self, cfg):
            super().__init__(cfg)
            self.decoder = decoder_factory(cfg)

    return JuniorBPolicy


if __name__ == "__main__":
    cfg = AttentionDecoderCfg()
    dec = AttentionDecoder(cfg)
    z = torch.randn(4, cfg.latent_dim)
    o = torch.randn(4, cfg.history * (3 * cfg.num_joints + 6))
    print("actions", tuple(dec(z, o).shape), "params", count_params(dec))
# Colab smoke / B0 microbench config (reduced from upstream paper defaults: 4096 envs, H=32).
# Consumed by code/train_entry.py and code/eval_entry.py. Values under `upstream:` are passed to the
# mjlab SuperMimic-style reproduction CLI (tyro flags) in --mode upstream; everything else is ours.

run_name: b0
seed: 0
policy: attention            # attention | mlp_matched | mlp_upstream   (B0 arms)

attention:                   # AttentionDecoderCfg overrides
  d_model: 128
  num_heads: 4
  num_self_attn_layers: 1
  query_hidden: [256]
  readout_hidden: [256, 128]
  descriptor: v2             # v2 (default, 16-d, morph_dim follows) | v1 (12-d)
  id_mode: morph             # morph (Junior-B arm) | index (ablation, breaks permutation equivariance)
  morphology: upstream_mjmodel   # upstream_mjmodel (Colab) | synthetic (CPU smoke fallback)

b2:
  mask_fracs: [0.1, 0.2]     # fraction of non-root joint tokens dropped at eval
  train_mask_frac: 0.0       # optional train-time token-drop augmentation (0 = off for B0)
  perm_trials: 8

smoke:                       # --mode smoke (CPU-capable, no simulator, no motion data)
  batch: 64
  horizon: 8
  steps: 20
  device: cpu

upstream:                    # --mode upstream (Colab GPU only)
  repo_dir: /content/SuperMimic-Reproduced
  # Upstream API identifier used to build the default-pose morphology (single place it is named).
  model_loader: "supermimic.data.motion_convert:load_g1_model"
  # Upstream robot entity config factory; its init_state.joint_pos (regex -> angle) is the env default
  # pose used for the descriptor default-angle column (seam S4). UNVERIFIED identifier: if it cannot
  # be imported, upstream mode fails loudly. Remove this key only to accept the qpos0-fallback.
  robot_cfg_loader: "mjlab.asset_zoo.robots.unitree_g1.g1_constants:get_g1_robot_cfg"
  # Env action scale (regex -> rad per unit; sigma = 0.25*effort/stiffness upstream). Descriptor v2 reads the
  # actuator effort limit / stiffness / damping from the robot entity config above and sigma from here
  # (single place the identifier is named). UNVERIFIED identifier; upstream mode fails loudly if missing or
  # not importable. Not needed with attention.descriptor: v1.
  action_scale_loader: "mjlab.asset_zoo.robots.unitree_g1.g1_constants:G1_ACTION_SCALE"
  # Upstream literal path inside the public retarget dataset (asset subdirectory).
  dataset_repo: lvhaidong/LAFAN1_Retargeting_Dataset
  dataset_subdir: g1
  npz_dir: data/npz/lafan1_smoke
  pass_clip_filter: false    # npz_dir is built from `clips` only, so no upstream name filter needed
  clips:                     # small LAFAN1-style subset (4 clips ~ walk/run/dance/jump; verified in dataset listing, packets/P1/fixes/FX3.md)
    - walk1_subject1
    - run1_subject2
    - dance1_subject1
    - jumps1_subject1
  tyro_args:
    --env.num-envs: 512             # T4: 256-512; L4: 512-1024
    --policy-trainer.batch-size: 512
    --policy-trainer.horizon: 16    # paper 32
    --policy-trainer.compile: None  # torch.compile off on first smoke (compile time dominates)
    --schedule.max-hours: 1.5
    --schedule.checkpoint-interval: 400
    --schedule.log-interval: 50
    --env.anchor-obs: true          # upstream deviation that lifts LAFAN1 return; same for both arms

eval:
  num_envs: 64
  out_dir: logs/eval

