/bin/bash -lc "python - <<'PY'
import json, pathlib, statistics as s, math, hashlib
p=pathlib.Path('orch/reports/VERDICT-P4-b0-attempt1-relaunch3-results.json')
d=json.loads(p.read_text())
print('P4 sha',hashlib.sha256(p.read_bytes()).hexdigest())
print('P4 verdict', {k:d[k] for k in ['verdict','b0_outcome','superior']})
a=d['attempts']
r={}
for arm in ['attention','mlp_matched']:
 r[arm]=[]
 for seed in range(3):
  key=f'b0_{arm}_s{seed}_a1'; v=a[key]['eval']['it0001600']; z=v['mask0.00']; t=v['mask0.20']
  print(key,'R_H',*[round(v['mask'+f]['r_h'],6) for f in ['0.00','0.10','0.20']], 'rho',*[round(v['mask'+f]['rho_h'],6) for f in ['0.10','0.20']], 'rho_step',round(t['rho_step'],6),'headroom',round((t['r_h']-.0393)/(z['r_h']-.0393),6),'surv',z['surv_steps'],t['surv_steps'])
  r[arm].append(v)
for f in ['0.10','0.20']:
 vals={arm:[x['mask'+f]['rho_h'] for x in r[arm]] for arm in r}
 sd={arm:s.stdev(v) for arm,v in vals.items()}
 print(f, 'SD',sd,'2SE',2*math.sqrt(sum(v*v/3 for v in sd.values())), 'delta_rho',s.mean(vals['attention'])-s.mean(vals['mlp_matched']))
absvals={arm:[x['mask0.20']['r_h'] for x in r[arm]] for arm in r}
print('delta_abs',s.mean(absvals['attention'])-s.mean(absvals['mlp_matched']),'2SE_abs',2*math.sqrt(sum(s.variance(v)/3 for v in absvals.values())))
print('R_floor',s.mean(a[f'b0_mlp_matched_s{i}_a1']['eval']['it0000400']['mask0.00']['r_h'] for i in range(3)))
PY"

